// --- Parametri Locali ---
float density = 10.0;  // Quante strisce vuoi
bool vertical = true;  // true = verticali, false = orizzontali

// --- Logica ---

// 1. We choose the coordinate to base it on (u or v)
// 'u' and 'v' are standard variables available in the shader template
float coord = vertical ? u : v;

// 2. We compute the alternating pattern
// We multiply the coordinate (0.0 -> 1.0) by the density.
// floor() creates integer steps (0, 1, 2, 3...)
// mod(..., 2.0) gives 0.0 or 1.0 alternately
float pattern = mod(floor(coord * density), 2.0);

// 3. Color mixing
// u_col1 and u_col2 are the uniforms passed from the interface (Color 1 and Color 2)
// If pattern is 0.0 -> gives u_col1
// If pattern is 1.0 -> gives u_col2
return mix(u_col1, u_col2, pattern);
